# -*- coding: utf-8 -*-
"""Science Stage 7 · Unit 13 Earth Processes – Read the lesson (shown below the video) and the lesson document (PDF).
Camday's own text, examples and questions; scope: Cambridge Lower Secondary Science 0893, Stage 7 (7ESp.01–7ESp.03, 7ESc.01)."""
from maths_notes_v4.kit4 import H, I, Y, X, K, L, W, BK, Ex, mcq, grid, num

READ = {}
CARD = lambda title, cards, cols=None: dict({"kind": "sciCards", "title": title, "cards": cards}, **({"cols": cols} if cols else {}))

# =====================================================================================================
# 13.1 Structure of the Earth · 7ESp.01
# =====================================================================================================
READ["13.1"] = L(
    H("Digging to the centre",
      "The deepest hole ever drilled went about 12 km down – and the rock at the bottom was hotter than 180 °C. The centre of the Earth is more than 500 times deeper.",
      "If nobody has ever been there, how do scientists know what is inside the Earth? Make a guess."),
    I("The layers of the Earth",
      "The Earth is made of layers, like a boiled egg: a thin shell, a thick middle and a centre.",
      fig={"kind": "sciEarth"},
      table=[["Layer", "What it is like"],
             ["**crust**", "thin layer of solid rock: about 5–10 km under oceans, up to 60–70 km under mountains"],
             ["**mantle**", "hot rock nearly 3000 km thick; the upper part is semi-molten and can flow very slowly; deeper down huge pressure keeps it solid"],
             ["**outer core**", "liquid iron and nickel"], ["**inner core**", "iron and nickel; the hottest layer (about 5400 °C) but solid because of the enormous pressure"]],
      then=["Scientists know this from **seismic waves** from earthquakes: the waves bend, speed up, slow down or stop as they pass through different layers."]),
    I("Real data: how thick are the layers?",
      "Approximate thickness of each layer (for the inner core, its radius):",
      fig={"kind": "barchart", "labels": ["crust", "mantle", "outer core", "inner core"], "values": [35, 2900, 2200, 1220], "ymax": 3000, "step": 500, "ylabel": "thickness (km)", "xlabel": "layer"},
      then=["The crust is so thin compared with the rest that it is like the skin on an apple. The mantle is the thickest layer."]),
    Y("Which layer?",
      grid("s7u13r11", "Which layer of the Earth is described?", ["Crust", "Mantle", "Outer core", "Inner core"],
           [("the thinnest layer, where we live", "Crust"), ("liquid iron and nickel", "Outer core"), ("the thickest layer", "Mantle"), ("the hottest layer, but solid", "Inner core")],
           "Use the table of layers.", "Thinnest = crust; liquid metal = outer core; thickest = mantle; hottest and solid = inner core.")),
    I("Tectonic plates",
      "The crust and the top of the mantle are broken into huge slabs called **tectonic plates**. They fit together like a jigsaw and rest on the mantle.",
      table=[["Kind of crust", "Density", "Where"], ["**oceanic**", "more dense, thinner", "the ocean floor"], ["**continental**", "less dense, thicker", "the continents"]],
      then=["Plates move very slowly – **1 to 10 cm a year**, about as fast as your fingernails grow. Heat from the core makes rock in the mantle rise, spread and sink in huge slow loops (**convection currents**), dragging the plates along.",
            "This explanation is the **model of plate tectonics**."]),
    Y("How far in a lifetime?",
      num("s7u13r12", "A plate moves 4 cm a year. How far does it move in 80 years, in metres?", 3.2, "First find the distance in cm, then divide by 100.",
          "4 × 80 = 320 cm = 3.2 m.", errs=[(320, "That is in cm – change it into metres.")])),
    K("Key points",
      "Layers: **crust** (thin, solid), **mantle** (thick, hot, partly flowing), **outer core** (liquid metal), **inner core** (solid, hottest).",
      "We learn about the inside of the Earth from seismic waves.",
      "The crust is broken into **tectonic plates** that move 1–10 cm a year, carried by convection in the mantle.",
      "Oceanic crust is denser than continental crust."),
    book=BK(
        [("crust", "the Earth's thin outer layer of solid rock"), ("mantle", "the thick layer of hot rock under the crust"), ("core", "the centre of the Earth, mainly iron and nickel"),
         ("tectonic plate", "a huge slab of the Earth's crust and upper mantle"), ("plate tectonics", "the model that the crust is made of moving plates")],
        [], [],
        [Ex("Name the four layers of the Earth from the outside in.", ans="crust, mantle, outer core, inner core"),
         Ex("Why is the inner core solid even though it is the hottest layer?", ans="The pressure there is enormous."),
         Ex("Give two differences between oceanic and continental crust.", ans="oceanic is denser and thinner; continental is less dense and thicker"),
         Ex("Explain what makes tectonic plates move.", ans="Heat from the core makes mantle rock rise, spread and sink (convection), dragging the plates."),
         Ex("Why is the crust compared to the skin of an apple?", ans="It is very thin compared with the whole Earth.", think=True)],
        ["describe the layers of the Earth", "describe tectonic plates and how they move", "compare oceanic and continental crust"],
        look=["the cut-away Earth", "the thickness chart"],
        note="Read it after the video: the layers of the Earth and tectonic plates (answers at the back)."),
)

# =====================================================================================================
# 13.2 Movement of tectonic plates · 7ESp.02
# =====================================================================================================
READ["13.2"] = L(
    H("Why there?",
      "Earthquakes and volcanoes are common in Japan, Indonesia and Chile, but rare in the middle of Australia.",
      "What do you think the 'earthquake countries' have in common?"),
    I("Where plates meet",
      "The edges of plates are called **plate boundaries**. Three kinds:",
      table=[["Boundary", "Plates …", "What happens"],
             ["**divergent**", "move apart", "magma rises into the gap: new crust, volcanoes, rift valleys"],
             ["**convergent**", "move towards each other", "fold mountains, volcanoes and earthquakes"],
             ["**transform**", "slide past each other", "earthquakes"]],
      fig={"kind": "plates", "boundary": "divergent"}),
    I("Predict, watch, explain: modelling fold mountains",
      "Four flat layers of coloured modelling clay are stacked like layers of rock and pushed slowly together from both ends.",
      then=["The layers **bend and fold upwards** into hills and valleys, still in the same order. This models two continental plates moving together at a **convergent boundary**.",
            "The Himalayas formed this way when the Indian plate pushed into the Eurasian plate – and they are still growing by a few millimetres a year."]),
    I("What causes earthquakes?",
      "Plates are always moving, but friction can make their edges **stick**. Stress builds up until the rocks suddenly slip.",
      then=["The energy is released as **seismic waves** (shock waves) that make the ground shake – an **earthquake**.",
            "The point underground where it starts is the **focus**; the point on the surface directly above is the **epicentre**. Damage is usually worst near the epicentre."]),
    I("How volcanoes form",
      "A **volcano** is an opening in the crust where **magma** (molten rock) and gases escape.",
      table=[["Step", "What happens"], ["1", "magma is less dense than the solid rock around it, so it rises"], ["2", "it collects in a **magma chamber**; pressure builds up"],
             ["3", "the magma forces its way up through a **vent** – an eruption"], ["4", "magma that reaches the surface is **lava**; layers of lava and ash build a cone"]],
      then=["There are about 1350 potentially active volcanoes. Magma also heats underground water – **geothermal power stations** use this thermal energy to generate electricity."]),
    Y("Which boundary?",
      grid("s7u13r21", "Which kind of plate boundary is described?", ["Divergent", "Convergent", "Transform"],
           [("plates collide and fold mountains form", "Convergent"), ("plates slide past each other", "Transform"), ("plates move apart and magma fills the gap", "Divergent")],
           "Apart, together or sideways?", "Together → convergent; sideways → transform; apart → divergent.")),
    Y("Epicentre",
      mcq("s7u13r22", "What is the epicentre of an earthquake?",
          [("the point on the surface directly above where it starts", True, "Yes."), ("the point underground where it starts", False, "That is the focus."),
           ("the top of a volcano", False, "That is the crater."), ("the edge of a plate", False, "That is a plate boundary.")],
          "Epi- means 'above'.", "The epicentre is on the surface above the focus.")),
    K("Key points",
      "Plate boundaries: **divergent** (apart), **convergent** (together), **transform** (sliding past).",
      "Earthquakes: stuck plates slip suddenly, releasing seismic waves; focus underground, epicentre above.",
      "Volcanoes: magma rises, pressure builds, lava erupts through a vent.",
      "Fold mountains form where continental plates push together (Himalayas)."),
    book=BK(
        [("plate boundary", "where two tectonic plates meet"), ("earthquake", "sudden shaking of the ground when plates slip"), ("seismic waves", "shock waves from an earthquake"),
         ("focus", "the point underground where an earthquake starts"), ("epicentre", "the point on the surface above the focus"),
         ("magma", "molten rock underground"), ("lava", "magma that reaches the surface"), ("fold mountains", "mountains formed when rock layers are pushed together and fold")],
        [], [],
        [Ex("Describe what happens at (a) a divergent (b) a convergent (c) a transform boundary.",
            ans="(a) plates move apart, magma rises, new crust / volcanoes (b) plates collide, fold mountains / volcanoes / earthquakes (c) plates slide past, earthquakes"),
         Ex("Explain how an earthquake happens.", ans="Friction makes the plate edges stick; stress builds until they slip suddenly, releasing energy as seismic waves."),
         Ex("Put in order: lava flows out; magma rises; pressure builds in the magma chamber; the volcano erupts.", ans="magma rises; pressure builds; the volcano erupts; lava flows out"),
         Ex("Explain why Indonesia has many earthquakes and volcanoes.", ans="It lies where several plates meet, at plate boundaries.", think=True)],
        ["describe the three kinds of plate boundary", "explain how earthquakes, volcanoes and fold mountains form"],
        look=["the boundary table", "the steps of an eruption"],
        note="Read it after the video: plate boundaries, earthquakes, volcanoes and fold mountains (answers at the back)."),
)

# =====================================================================================================
# 13.3 The Earth's atmosphere · 7ESp.03
# =====================================================================================================
READ["13.3"] = L(
    H("What are you breathing?",
      "Take a deep breath. Most people think the air is mainly oxygen.",
      "Guess the percentage of oxygen in the air before you read on."),
    I("What makes up the air?",
      "The **atmosphere** is the layer of gases around the Earth. Clean, dry air is a **mixture** of gases.",
      fig={"kind": "pie", "labels": ["nitrogen 78%", "oxygen 21%", "argon, carbon dioxide, other 1%"], "values": [78, 21, 1]},
      then=["Nitrogen and oxygen make up 99% of dry air. Carbon dioxide is only about 0.04% – but even small changes in it have big effects.",
            "Real air also contains **water vapour**. The amount (**humidity**) is higher on warm days, because warm air can hold more water vapour."]),
    Y("Most common gas",
      mcq("s7u13r31", "Which gas makes up most of the air?",
          [("nitrogen", True, "Yes – about 78%."), ("oxygen", False, "Oxygen is about 21%."), ("carbon dioxide", False, "Only about 0.04%."), ("argon", False, "Less than 1%.")],
          "About four-fifths of the air.", "Nitrogen is about 78% of the air.")),
    I("How the air changes",
      "The composition of the air changes because of natural events and human activity.",
      table=[["Source", "What it adds"], ["volcanic eruptions", "ash, carbon dioxide, water vapour, sulfur dioxide"], ["respiration by living things", "carbon dioxide"],
             ["photosynthesis", "removes carbon dioxide and adds oxygen"], ["burning fossil fuels in vehicles, factories and power stations", "carbon dioxide, sulfur dioxide, oxides of nitrogen, tiny particles (particulates)"],
             ["cutting down and burning forests", "carbon dioxide – and fewer trees are left to absorb it"]],
      then=["Particulates and nitrogen oxides cause breathing problems; sulfur dioxide and nitrogen oxides cause acid rain."]),
    I("Real data: carbon dioxide in the air",
      "Scientists have measured carbon dioxide at an observatory on a Hawaiian mountain since 1958 (parts per million, ppm):",
      fig={"kind": "linegraph", "x": {"min": 1960, "max": 2025, "step": 10, "label": "year"}, "y": {"min": 300, "max": 440, "step": 20, "label": "carbon dioxide (ppm)"},
           "series": [{"pts": [[1960, 317], [1970, 326], [1980, 339], [1990, 354], [2000, 370], [2010, 390], [2020, 414], [2025, 426]]}]},
      then=["The level has risen every decade, from about 317 ppm in 1960 to about 426 ppm today – and the line is getting **steeper**. The main cause is burning fossil fuels."]),
    Y("Read the graph",
      num("s7u13r32", "Use the graph. By how many ppm did carbon dioxide rise from 1980 to 2020?", 75, "Read the values at 1980 and 2020 and subtract.",
          "414 − 339 = 75 ppm.", errs=[(753, "Subtract the two readings.")])),
    I("Monitoring carbon dioxide",
      "Carbon dioxide traps heat, so more of it causes **global warming** and **climate change**.",
      then=["Instruments on satellites and on the International Space Station now measure carbon dioxide all over the world, many thousands of times a day. The data show that tropical forests absorb a lot of carbon dioxide – and that burning them releases it. Information like this helps countries plan solutions."]),
    K("Key points",
      "Dry air: about **78% nitrogen, 21% oxygen, 1%** argon, carbon dioxide and other gases; plus water vapour.",
      "Volcanoes and respiration add gases; photosynthesis removes carbon dioxide.",
      "Burning fossil fuels adds carbon dioxide and pollutants such as sulfur dioxide and particulates.",
      "Carbon dioxide has risen steadily since measurements began – causing global warming."),
    book=BK(
        [("atmosphere", "the layer of gases around the Earth"), ("humidity", "the amount of water vapour in the air"), ("pollutant", "a harmful substance added to the environment"),
         ("particulates", "tiny solid particles in the air"), ("global warming", "the rise in the Earth's average temperature")],
        [], [],
        [Ex("Give the approximate percentages of nitrogen and oxygen in dry air.", ans="nitrogen 78%, oxygen 21%"),
         Ex("Name two natural processes and two human activities that change the air.", ans="natural: volcanic eruptions, respiration (photosynthesis); human: burning fossil fuels, deforestation"),
         Ex("Use the graph: estimate the carbon dioxide level in 2000.", ans="about 370 ppm"),
         Ex("Explain why cutting down and burning forests increases carbon dioxide in two ways.", ans="Burning releases carbon dioxide, and fewer trees remain to absorb it by photosynthesis.", think=True)],
        ["describe the composition of air", "explain how natural events and pollution change the air", "interpret carbon dioxide data"],
        look=["the pie chart of air", "the carbon dioxide graph"],
        note="Read it after the video: what air is made of, how it changes and the carbon dioxide data (answers at the back)."),
)

# =====================================================================================================
# 13.4 The water cycle · 7ESc.01
# =====================================================================================================
READ["13.4"] = L(
    H("Old water",
      "The water in your glass today may once have been drunk by a dinosaur, floated in the Pacific Ocean or fallen as snow on a mountain.",
      "How can the same water keep going round and round? Read on."),
    I("The water cycle",
      "Water moves continuously between the oceans, the air and the land. Energy from the **Sun** drives the cycle.",
      fig={"kind": "sciCycle", "title": "The water cycle", "steps": ["Evaporation from seas and lakes", "Condensation into clouds", "Precipitation: rain, snow, hail",
                                                                   "Run-off and groundwater back to the sea"], "centre": "driven by the Sun"},
      table=[["Stage", "What happens"],
             ["**evaporation**", "the Sun heats water in oceans, lakes and rivers; it turns into water vapour and rises (plants also give off water vapour from their leaves – **transpiration**)"],
             ["**condensation**", "rising water vapour cools and forms tiny droplets: clouds"], ["**precipitation**", "droplets join, grow heavy and fall as rain, snow or hail"],
             ["**collection**", "water flows over the land (**run-off**) into rivers and the sea; some soaks into the ground (**groundwater**)"]]),
    Y("Name the stage",
      grid("s7u13r41", "Which stage of the water cycle is it?", ["Evaporation", "Condensation", "Precipitation", "Run-off"],
           [("clouds form over the mountains", "Condensation"), ("a puddle dries in the sun", "Evaporation"), ("hail falls on a town", "Precipitation"), ("rainwater flows down a hill into a stream", "Run-off")],
           "Liquid to gas, gas to liquid, falling, or flowing?", "Clouds forming = condensation; drying = evaporation; hail = precipitation; flowing to a stream = run-off.")),
    I("Predict, watch, explain: a water cycle in a bowl",
      "A bowl of warm salty water with an empty cup in the middle is covered with cling film. An ice cube sits on the film, just above the cup. The bowl is left in the sun.",
      then=["Drops form under the cling film, run to the lowest point and drip into the cup. The water in the cup **does not taste salty**.",
            "The water **evaporated** but the salt stayed behind; the vapour **condensed** on the cold film and fell as 'rain' (**precipitation**). This is also a way to get drinking water from sea water."]),
    Y("Why not salty?",
      mcq("s7u13r42", "Why is rain not salty, even though most of it comes from the sea?",
          [("Only the water evaporates; the salt stays behind in the sea.", True, "Yes."), ("The salt is filtered out by the clouds.", False, "Clouds do not filter."),
           ("Rain comes only from rivers.", False, "Most water vapour comes from the oceans."), ("The salt sinks to the bottom of the clouds.", False, "The salt never leaves the sea.")],
          "What happens to salt water when it evaporates?", "Evaporation leaves dissolved salt behind, so water vapour – and rain – is fresh.")),
    K("Key points",
      "The **water cycle**: evaporation → condensation → precipitation → run-off / groundwater → back to the sea.",
      "The Sun's energy drives the cycle.",
      "Evaporation leaves salt behind, so rain is fresh water."),
    book=BK(
        [("water cycle", "the continuous movement of water between the sea, the air and the land"), ("evaporation", "liquid water turning into water vapour"),
         ("condensation", "water vapour cooling into liquid droplets"), ("precipitation", "water falling from clouds as rain, snow or hail"),
         ("run-off", "water flowing over the land into rivers"), ("groundwater", "water that has soaked into the ground")],
        [], [],
        [Ex("Draw and label a diagram of the water cycle.", ans="sea → evaporation → clouds (condensation) → precipitation → run-off / groundwater → sea"),
         Ex("Where does the energy for the water cycle come from?", ans="the Sun"),
         Ex("In the bowl model, which part represents: (a) the sea (b) clouds (c) rain?", ans="(a) the salty water (b) drops under the cling film (c) drops falling into the cup"),
         Ex("Quick quiz.", ("Which layer of the Earth is the hottest?", "the inner core"), ("Which type of boundary forms fold mountains?", "convergent"),
            ("Which gas makes up most of the air?", "nitrogen"), ("Name the process in which water vapour turns into cloud droplets.", "condensation"))],
        ["describe the stages of the water cycle", "explain the bowl model", "explain why rain is not salty"],
        look=["the water cycle diagram", "the bowl model"],
        note="Read it after the video: the water cycle, the bowl model and a quick quiz (answers at the back)."),
)
